290	// than the latest checkpointed commit (0 when HEAD has the checkpoint or the
291	// count cannot be determined; best-effort).
292	func trailResumeCheckpointBehindHead(ctx context.Context, branch string) int {
293		repo, err := openRepository(ctx)
294		if err != nil {
