296				slog.String("error", err.Error()))
297			return 0
298		}
299		defer repo.Close()
300		result, err := findBranchCheckpoints(repo, branch)
301		if err != nil {
302			logging.Debug(ctx, "trail resume json: behind-head count unavailable",
303				slog.String("error", err.Error()))
304			return 0
305		}
306		if result == nil || !result.newerCommitsExist {
307			return 0
308		}
309		return result.newerCommitCount
