func parseTrailResumeRepoFlag(value string) (trailResumeRepository, error) {
	value = strings.TrimSpace(value)
	if value == "" {
		return trailResumeRepository{}, nil
	}
	owner, repo, err := parseGitHubURL(value)
	if err != nil {
		return trailResumeRepository{}, err
